// test-hardening row 12 — generative, structure-aware fuzz of the SSE parser
// through the REAL public seam: streamChat with a stubbed fetchImpl whose
// body is a fast-check-generated byte stream. No mock server, no network.
//
// Properties (each is a contract of runtime/dsh/llm.js, never an
// implementation detail):
//   P1 reassembly — for ANY well-formed stream split at ANY byte boundary
//      (multi-byte UTF-8 included, \n or \r\n, SSE comments interleaved),
//      text/reasoning reassemble to the concatenation of the generated
//      pieces and the delta counters match.
//   P2 typed failure — an unparsable `data:` line rejects with
//      LlmError('invalid'), never an accidental TypeError (rule 5).
//   P3 post-[DONE] silence — bytes after the [DONE] terminator are drained,
//      not folded: even unparsable trailing lines cannot fail the run
//      (measured 2026-09-30, the onboarding round).
import { describe, it, expect } from 'vitest';
import fc from 'fast-check';
import { streamChat, LlmError } from '../../../runtime/dsh/llm.js';

// UTF-8-heavy alphabet on purpose: the byte-splitter must survive cuts
// INSIDE a multi-byte character (the makeUtf8 decoder's whole job).
const PIECE_CHARS = 'aZ9 启动🚀 é漢';
const pieceArb = fc.string({ unit: fc.constantFrom(...PIECE_CHARS.split('')), minLength: 1, maxLength: 8 });

// One well-formed chat.completion stream as TEXT (newline-joined SSE).
const sseTextArb = fc
  .tuple(
    fc.array(pieceArb, { minLength: 1, maxLength: 12 }),
    fc.array(pieceArb, { maxLength: 6 }),
    fc.constantFrom('\n', '\r\n'),
    fc.boolean()
  )
  .map(([contents, reasonings, nl, withComments]) => {
    const model = { model: 'gen-1', choices: [{ delta: {} }] };
    const lines = [];
    if (withComments) lines.push(': keep-alive comment', 'event: ping', 'id: 1');
    lines.push(`data: ${JSON.stringify(model)}`);
    const pairs = contents.map((c) => ({ delta: { content: c } }));
    reasonings.forEach((r, i) => pairs.splice(Math.min(i * 2, pairs.length), 0, { delta: { reasoning_content: r } }));
    for (const p of pairs) {
      if (withComments && Math.random() === -1) lines.push(': never'); // deterministic: no-op
      lines.push(`data: ${JSON.stringify({ choices: [p] })}`);
    }
    lines.push(`data: ${JSON.stringify({ choices: [{ delta: {}, finish_reason: 'stop' }] })}`);
    lines.push('data: [DONE]');
    return { text: lines.join(nl) + nl, contents, reasonings, model };
  });

// Split a UTF-8 buffer at the given offsets (sorted/deduped) into ≥1 chunks.
const chunkBytes = (text, cuts) => {
  const buf = Buffer.from(text, 'utf8');
  const at = [...new Set(cuts)].sort((a, b) => a - b).filter((c) => c > 0 && c < buf.length);
  const chunks = [];
  let prev = 0;
  for (const c of at) {
    chunks.push(buf.subarray(prev, c));
    prev = c;
  }
  chunks.push(buf.subarray(prev));
  return chunks;
};

const transportFor = (chunks) =>
  async () => ({
    status: 200,
    headers: {},
    abort: () => {},
    body: (async function* () {
      for (const c of chunks) yield c;
    })(),
  });

const runStream = (chunks) =>
  streamChat({
    fetchImpl: transportFor(chunks),
    baseUrl: 'http://127.0.0.1:9',
    apiKey: 'k',
    model: 'gen-1',
    messages: [{ role: 'user', content: 'hi' }],
  });

// P1: reassembly under arbitrary byte chunking (multi-byte UTF-8 cuts).
const p1Reassembly = async () => {
  await fc.assert(
    fc.asyncProperty(
      sseTextArb,
      fc.array(fc.nat(400), { maxLength: 24 }),
      async (stream, cuts) => {
        const chunks = chunkBytes(stream.text, cuts);
        const res = await runStream(chunks);
        expect(res.text).toBe(stream.contents.join(''));
        expect(res.reasoning).toBe(stream.reasonings.join(''));
        expect(res.deltas).toBe(stream.contents.length);
        expect(res.reasoningDeltas).toBe(stream.reasonings.length);
        expect(res.finishReason).toBe('stop');
        expect(res.served).toBe('gen-1');
      }
    ),
    { numRuns: 40, timeout: 60000 }
  );
};

describe('llm-sse fuzz (row 12): the real streamChat against generated SSE byte streams', () => {
  it('P1 reassembly: text/reasoning/counters survive any byte chunking', { timeout: 90000 }, p1Reassembly);

  it('P2 typed failure: an unparsable data line rejects LlmError invalid', { timeout: 60000 }, p2TypedFailure);
});

// P2: an unparsable data line rejects typed LlmError('invalid') — rule 5.
const p2TypedFailure = async () => {
  await fc.assert(
    fc.asyncProperty(
      fc.string({ minLength: 0, maxLength: 40 }).filter((s) => !s.includes('\n')),
      async (junk) => {
        const text = `data: {oo${junk}\ndata: [DONE]\n`;
        await expect(runStream(chunkBytes(text, [3, 9]))).rejects.toThrow(LlmError);
      }
    ),
    { numRuns: 30, timeout: 60000 }
  );
  await expect(runStream(chunkBytes('data: {oo\n', []))).rejects.toMatchObject({
    code: 'invalid',
  });
};

// P3: bytes after [DONE] are drained, not folded — even unparsable ones.
const p3PostDoneSilence = async () => {
  await fc.assert(
    fc.asyncProperty(
      fc.string({ minLength: 0, maxLength: 60 }).filter((s) => !s.includes('\n')),
      pieceArb,
      async (junk, piece) => {
        const text = `data: ${JSON.stringify({ choices: [{ delta: { content: piece } }] })}\n` +
          'data: [DONE]\n' +
          `data: {oo${junk}\n`;
        const res = await runStream(chunkBytes(text, [5, 30]));
        expect(res.text).toBe(piece);
      }
    ),
    { numRuns: 30, timeout: 60000 }
  );
};
